    "settings.perio.row.gm": "Ínyszél helyzete (GM)",
    "settings.perio.row.gm.desc": "Az ínyszél helyzete a zománc-cement határhoz (CEJ) képest, előjeles mm. Pozitív = ínyrecesszió, negatív = duzzadt/koronális ínyszél.",
    "settings.perio.row.cal": "Tapadási nívó (CAL)",
    "settings.perio.row.cal.desc": "CAL = tasakmélység + ínyszél, a CEJ-től a tasak aljáig; a valódi, referencia-stabil tapadásvesztés-mérték.",
    "settings.perio.row.bop": "Vérzés szondázásra (BOP)",
