    "credits.title": "Über das Projekt und Danksagungen",
    "credits.intro": "React Advanced Odontogram ist ein interaktives Werkzeug zur Zahnbefundung. Sie können Befunde Zahn für Zahn erfassen, die Behandlung planen, das Parodontium dokumentieren und alles als JSON, FHIR oder als Bericht im PDF Format exportieren. Es läuft vollständig im Browser und funktioniert eigenständig oder innerhalb einer größeren Anwendung.",
