    "perio.info.button": "{{label}} – informazioni",
    "perio.info.pd": "Profondità di sondaggio — distanza in mm dal margine gengivale al fondo della tasca. ≤3 mm è sano; una tasca più profonda indica infiammazione/perdita di attacco.",
    "perio.info.gm": "Posizione del margine gengivale rispetto al limite amelo-cementizio (CEJ), in mm con segno. Positivo = recessione gengivale (verso la radice), negativo = margine coronale/edematoso.",
    "perio.info.cal": "Livello di attacco clinico (CAL = profondità di sondaggio + margine gengivale) — dal CEJ al fondo della tasca; la vera misura, stabile come riferimento, della perdita di attacco.",
    "perio.info.bop": "Sanguinamento al sondaggio — indicatore di infiammazione (attività). %BOP è la percentuale di siti sanguinanti; <10% è sano.",
    "perio.info.plaque": "Indice di placca di O'Leary — presenza di placca sulle 4 superfici del dente; PI% è la percentuale di superfici con placca (igiene orale).",
    "perio.info.furcation": "Coinvolgimento della forcazione (Glickman I–IV) alla biforcazione radicolare dei denti pluriradicolati; il grado II–III è un fattore aggravante nella stadiazione.",
    "perio.info.mobility": "Mobilità dentale (Miller 0–III) — riflette la perdita di attacco/trauma occlusale.",
    "perio.info.cej": "Rilevabilità della giunzione amelo-cementizia (CEJ) — influisce sulla precisione della misurazione di CAL/recessione.",
    "perio.info.rootConcavity": "Concavità della superficie radicolare; una concavità profonda è più difficile da pulire e guarisce peggio.",
    "perio.info.pi": "Indice di placca di Silness–Löe (0–3) per superficie (mesiale/distale/vestibolare/linguale) — classifica la quantità/spessore della placca, un indicatore dell'igiene orale.",
    "perio.info.gi": "Indice gengivale di Löe–Silness (0–3) per superficie — classifica la gravità dell'infiammazione gengivale (colore, edema, tendenza al sanguinamento).",
    "perio.info.mpi": "Indice di placca modificato di Mombelli (0–3) per superficie implantare (mesiale/distale/vestibolare/linguale) — 0 nessuna placca, 1 placca rilevabile solo con la sonda, 2 placca visibile a occhio nudo, 3 deposito molle abbondante.",
    "perio.info.mbi": "Indice di sanguinamento del solco modificato di Mombelli (0–3) per superficie implantare — 0 nessun sanguinamento al sondaggio, 1 punti di sanguinamento isolati, 2 linea di sangue continua sul margine, 3 sanguinamento abbondante/profuso.",
    "perio.info.kg": "Larghezza (mm) della gengiva cheratinizzata (aderente) sulla superficie vestibolare del dente; una banda stretta (<2 mm) è un fattore di rischio mucogengivale.",
    "perio.info.gt": "Spessore gengivale (biotipo) — un fenotipo sottile è più incline a recessione e complicanze estetiche.",
    "perio.info.miller": "Classificazione di Miller della recessione gengivale (I–IV) — indica l'estensione della recessione e il successo atteso del ricoprimento radicolare.",
    "settings.perio.group.pocket": "Sondaggio parodontale",
    "settings.perio.group.hygiene": "Igiene",
    "settings.perio.group.mucogingival": "Mucogengivale",
    "settings.perio.group.support": "Supporto",
    "settings.perio.group.periimplant": "Perimplantare",
    "settings.perio.row.pd": "Profondità di sondaggio (PD)",
    "settings.perio.row.pd.desc": "Distanza in mm dal margine gengivale al fondo della tasca. ≤3 mm è sano; una tasca più profonda indica infiammazione/perdita di attacco.",
    "settings.perio.row.gm": "Margine gengivale (GM)",
    "settings.perio.row.gm.desc": "Posizione del margine gengivale rispetto al limite amelo-cementizio (CEJ), in mm con segno. Positivo = recessione, negativo = margine coronale/edematoso.",
    "settings.perio.row.cal": "Livello di attacco clinico (CAL)",
    "settings.perio.row.cal.desc": "CAL = profondità di sondaggio + margine gengivale, dal CEJ al fondo della tasca; la vera misura, stabile come riferimento, della perdita di attacco.",
    "settings.perio.row.bop": "Sanguinamento al sondaggio (BOP)",
    "settings.perio.row.bop.desc": "Indicatore di infiammazione (attività). %BOP è la percentuale di siti sanguinanti; <10% è sano.",
    "settings.perio.row.plaque": "Indice di placca",
    "settings.perio.row.plaque.desc": "Indice di placca di O'Leary — presenza di placca sulle 4 superfici del dente; PI% è la percentuale di superfici con placca (igiene orale).",
    "settings.perio.row.pi": "Indice di placca (PI)",
    "settings.perio.row.pi.desc": "Indice di placca di Silness–Löe (0–3) per superficie — classifica la quantità/spessore della placca.",
