    "credits.title": "O aplikácii a poďakovania",
    "credits.intro": "React Advanced Odontogram je interaktívny nástroj na zaznamenávanie zubných nálezov. Môžete zaznamenávať nálezy zub po zube, plánovať liečbu, zaznamenať parodont a exportovať všetko ako JSON, FHIR alebo správu vo formáte PDF. Beží úplne v prehliadači a funguje samostatne alebo v rámci väčšej aplikácie.",
