    "perio.info.button": "{{label}} – informacje",
    "perio.info.pd": "Głębokość kieszonki (PD) — odległość w mm od brzegu dziąsła do dna kieszonki. ≤3 mm jest zdrowe; głębsza kieszonka wskazuje na stan zapalny/utratę przyczepu.",
    "perio.info.gm": "Położenie brzegu dziąsła względem granicy szkliwno-cementowej (CEJ), w mm ze znakiem. Wartość dodatnia = recesja dziąsła (w stronę korzenia), ujemna = obrzęknięty/koronowy brzeg.",
    "perio.info.cal": "Kliniczny poziom przyczepu (CAL = głębokość kieszonki + położenie brzegu dziąsła) — od CEJ do dna kieszonki; rzeczywista, stabilna referencyjnie miara utraty przyczepu.",
    "perio.info.bop": "Krwawienie przy zgłębnikowaniu — wskaźnik stanu zapalnego (aktywności). %BOP to odsetek krwawiących miejsc; <10% jest zdrowe.",
    "perio.info.plaque": "Wskaźnik płytki O'Leary'ego — obecność płytki na 4 powierzchniach zęba; PI% to odsetek powierzchni pokrytych płytką (higiena jamy ustnej).",
    "perio.info.furcation": "Zajęcie furkacji (Glickman I–IV) w miejscu rozgałęzienia korzeni zębów wielokorzeniowych; stopień II–III jest czynnikiem obciążającym przy określaniu stadium.",
    "perio.info.mobility": "Ruchomość zęba (Miller 0–III) — odzwierciedla utratę przyczepu/uraz okluzyjny.",
    "perio.info.cej": "Wykrywalność granicy szkliwno-cementowej (CEJ) — wpływa na dokładność pomiaru CAL/recesji.",
    "perio.info.rootConcavity": "Wklęsłość powierzchni korzenia; głęboka wklęsłość jest trudniejsza do oczyszczenia i gorzej się goi.",
    "perio.info.pi": "Wskaźnik płytki Silness–Löe (0–3) dla każdej powierzchni (mezjalna/dystalna/policzkowa/językowa) — ocenia ilość/grubość płytki nazębnej, wskaźnik higieny jamy ustnej.",
    "perio.info.gi": "Wskaźnik dziąsłowy Löe–Silness (0–3) dla każdej powierzchni — ocenia nasilenie stanu zapalnego dziąsła (kolor, obrzęk, skłonność do krwawienia).",
    "perio.info.mpi": "Zmodyfikowany wskaźnik płytki wg Mombelli (0–3) dla każdej powierzchni implantu (mezjalna/dystalna/policzkowa/językowa) — 0 brak płytki, 1 płytka wykrywalna tylko sondą, 2 płytka widoczna gołym okiem, 3 obfity miękki osad.",
    "perio.info.mbi": "Zmodyfikowany wskaźnik krwawienia z bruzdy wg Mombelli (0–3) dla każdej powierzchni implantu — 0 brak krwawienia przy sondowaniu, 1 pojedyncze punkty krwawienia, 2 ciągła linia krwi na brzegu dziąsła, 3 obfite/silne krwawienie.",
    "perio.info.kg": "Szerokość (mm) dziąsła zrogowaciałego (przyczepionego) na powierzchni policzkowej zęba; wąskie pasmo (<2 mm) to czynnik ryzyka śluzówkowo-dziąsłowego.",
    "perio.info.gt": "Grubość dziąsła (biotyp) — cienki fenotyp jest bardziej podatny na recesję i powikłania estetyczne.",
    "perio.info.miller": "Klasyfikacja Millera recesji dziąsłowej (I–IV) — wskazuje zasięg recesji i oczekiwaną skuteczność pokrycia korzenia.",
    "settings.perio.group.pocket": "Karta kieszonek",
    "settings.perio.group.hygiene": "Higiena",
    "settings.perio.group.mucogingival": "Śluzówkowo-dziąsłowe",
    "settings.perio.group.support": "Tkanki podporowe",
    "settings.perio.group.periimplant": "Okołowszczepowe",
    "settings.perio.row.pd": "Głębokość kieszonki (PD)",
    "settings.perio.row.pd.desc": "Odległość w mm od brzegu dziąsła do dna kieszonki. ≤3 mm jest zdrowe; głębsza kieszonka wskazuje na stan zapalny/utratę przyczepu.",
    "settings.perio.row.gm": "Położenie brzegu dziąsła (GM)",
    "settings.perio.row.gm.desc": "Położenie brzegu dziąsła względem granicy szkliwno-cementowej (CEJ), w mm ze znakiem. Wartość dodatnia = recesja, ujemna = obrzęknięty/koronowy brzeg.",
    "settings.perio.row.cal": "Kliniczny poziom przyczepu (CAL)",
    "settings.perio.row.cal.desc": "CAL = głębokość kieszonki + położenie brzegu dziąsła, od CEJ do dna kieszonki; rzeczywista, stabilna referencyjnie miara utraty przyczepu.",
    "settings.perio.row.bop": "Krwawienie przy zgłębnikowaniu (BOP)",
    "settings.perio.row.bop.desc": "Wskaźnik stanu zapalnego (aktywności). %BOP to odsetek krwawiących miejsc; <10% jest zdrowe.",
    "settings.perio.row.plaque": "Wskaźnik płytki",
    "settings.perio.row.plaque.desc": "Wskaźnik płytki O'Leary'ego — obecność płytki na 4 powierzchniach zęba; PI% to odsetek powierzchni pokrytych płytką (higiena jamy ustnej).",
    "settings.perio.row.pi": "Wskaźnik płytki (PI)",
    "settings.perio.row.pi.desc": "Wskaźnik płytki Silness–Löe (0–3) dla każdej powierzchni — ocenia ilość/grubość płytki nazębnej.",
    "settings.perio.row.gi": "Wskaźnik dziąsłowy (GI)",
    "settings.perio.row.gi.desc": "Wskaźnik dziąsłowy Löe–Silness (0–3) dla każdej powierzchni — ocenia nasilenie stanu zapalnego dziąsła.",
    "settings.perio.row.cej": "Widoczność granicy szkliwno-cementowej (CEJ)",
    "settings.perio.row.cej.desc": "Wykrywalność granicy szkliwno-cementowej (CEJ) — wpływa na dokładność pomiaru CAL/recesji.",
    "settings.perio.row.rootConcavity": "Wklęsłość korzenia",
    "settings.perio.row.rootConcavity.desc": "Wklęsłość powierzchni korzenia; głęboka wklęsłość jest trudniejsza do oczyszczenia i gorzej się goi.",
    "settings.perio.row.kg": "Dziąsło zrogowaciałe (KG)",
    "settings.perio.row.kg.desc": "Szerokość (mm) dziąsła zrogowaciałego (przyczepionego) na powierzchni policzkowej zęba; wąskie pasmo (<2 mm) to czynnik ryzyka śluzówkowo-dziąsłowego.",
    "settings.perio.row.gt": "Grubość dziąsła (GT)",
    "settings.perio.row.gt.desc": "Grubość dziąsła (biotyp) — cienki fenotyp jest bardziej podatny na recesję i powikłania estetyczne.",
    "settings.perio.row.furcation": "Furkacja",
    "settings.perio.row.furcation.desc": "Zajęcie furkacji (Glickman I–IV) w miejscu rozgałęzienia korzeni zębów wielokorzeniowych; stopień II–III jest czynnikiem obciążającym.",
    "settings.perio.row.mobility": "Ruchomość",
