    "credits.title": "O aplikacji i podziękowania",
    "credits.intro": "React Advanced Odontogram to interaktywne narzędzie do rejestrowania stanu uzębienia. Możesz rejestrować nieprawidłowości ząb po zębie, planować leczenie, dokumentować przyzębie i eksportować wszystko jako JSON, FHIR lub raport w formacie PDF. Działa w całości w przeglądarce i sprawdza się samodzielnie lub w ramach większej aplikacji.",
