    "credits.title": "Sobre e créditos",
    "credits.intro": "React Advanced Odontogram é uma ferramenta interativa de registro odontológico. Você pode registrar achados dente por dente, planejar o tratamento, documentar o periodonto e exportar tudo como JSON, FHIR ou um relatório em PDF. Funciona inteiramente no navegador e serve sozinho ou dentro de um aplicativo maior.",
