    "perio.info.button": "{{label}} – 信息",
    "perio.info.pd": "探诊深度 — 从牙龈缘到袋底的距离（毫米）。≤3 毫米为健康；更深的牙周袋提示炎症/附着丧失。",
    "perio.info.gm": "牙龈缘相对于釉牙骨质界（CEJ）的位置，以带符号的毫米数表示。正值 = 牙龈退缩（向根方），负值 = 龈缘肿胀/位于冠方。",
    "perio.info.cal": "临床附着水平（CAL = 探诊深度 + 牙龈缘位置）— 从 CEJ 到袋底的距离；反映附着丧失的真实、稳定参考指标。",
    "perio.info.bop": "探诊出血 — 炎症活动性的指标。BOP% 为出血位点所占比例；<10% 为健康。",
    "perio.info.plaque": "O'Leary 菌斑指数 — 牙齿 4 个面上菌斑的存在情况；PI% 为被菌斑覆盖表面所占比例（口腔卫生指标）。",
    "perio.info.furcation": "根分叉病变（Glickman I–IV 级）— 发生于多根牙根分叉处；II–III 度是分期中的加重因素。",
    "perio.info.mobility": "牙齿松动度（Miller 0–III 级）— 反映附着丧失/咬合创伤。",
    "perio.info.cej": "釉牙骨质界（CEJ）的可探及程度 — 影响 CAL/牙龈退缩测量的准确性。",
    "perio.info.rootConcavity": "根面凹陷；深凹陷更难清洁，愈合效果也较难预测。",
    "perio.info.pi": "Silness–Löe 菌斑指数（0–3）按牙面（近中/远中/颊侧/舌侧）评分 — 评估牙面菌斑的量/厚度，是口腔卫生指标。",
    "perio.info.gi": "Löe–Silness 牙龈指数（0–3）按牙面评分 — 评估牙龈炎症的严重程度（颜色、水肿、出血倾向）。",
    "perio.info.mpi": "Mombelli 改良菌斑指数（0–3）按种植体表面（近中/远中/颊侧/舌侧）评分 — 0 级无菌斑，1 级仅探针划过表面时可见菌斑，2 级肉眼可见菌斑，3 级大量软垢堆积。",
    "perio.info.mbi": "Mombelli 改良龈沟出血指数（0–3）按种植体表面评分 — 0 级探诊无出血，1 级孤立出血点，2 级沿龈缘连续的血线，3 级大量/严重出血。",
    "perio.info.kg": "牙齿颊侧角化（附着）龈的宽度（毫米）；窄带（<2 毫米）是黏膜龈危险因素。",
    "perio.info.gt": "牙龈厚度（生物型）— 薄型更易发生牙龈退缩及美学并发症。",
    "perio.info.miller": "牙龈退缩的 Miller 分类（I–IV 级）— 表明退缩程度及根面覆盖成功的预期概率。",
