    "credits.title": "关于与致谢",
    "credits.intro": "React Advanced Odontogram 是一款交互式牙科记录工具。您可以逐颗牙齿记录检查所见，规划治疗，记录牙周组织，并将全部内容导出为 JSON、FHIR 或 PDF 报告。它完全在浏览器中运行，既可独立使用，也可嵌入更大的应用程序中。",
    "credits.creatorTitle": "创建者和主要开发者",
    "credits.contributorsTitle": "贡献者",
    "credits.contrib.zoliqua": "整个引擎的创建者和主要开发者。",
    "credits.contrib.odontodev": "状态注水与生命周期 API，作为受控属性的充填设置，幂等的设置方法以及可折叠卡片。",
    "credits.contrib.julianobazzi": "巴西葡萄牙语翻译。",
    "credits.contrib.yassine": "法语翻译以及候选的测量解剖结构。",
    "credits.contrib.saegerdirk": "测量的牙齿解剖结构和牙齿生成器，以及可组合接口的提案。",
    "credits.librariesTitle": "使用以下技术构建",
