    "intro.settings.text": "افتح الإعدادات لتبديل نظام الترقيم (FDI, Universal, Palmer)، وتفعيل مخطط اللثة، وضبط كل شيء آخر.",
    "intro.perioView.title": "عرض اللثة",
    "intro.perioView.text": "انتقل إلى عرض اللثة لتسجيل الجيوب والانحسار والنزيف.",
    "intro.perioChart.title": "تخطيط اللثة",
    "intro.perioChart.text": "سجّل أعماق السبر وحواف اللثة لكل موضع. يُحسب التصنيف المرحلي والدرجة تلقائيًا.",
    "intro.export.title": "التصدير",
    "intro.export.text": "صدّر المخطط بصيغة JSON أو FHIR أو PNG أو JPG أو SVG أو كتقرير PDF.",
    "intro.import.title": "الاستيراد",
    "intro.import.text": "حمّل مخططًا سابقًا من ملف JSON أو FHIR.",
    "intro.done.title": "أنت جاهز",
    "intro.done.text": "هذه هي الجولة. استكشف بقية الميزات على راحتك.",
    "credits.title": "حول التطبيق والشكر",
    "credits.intro": "React Advanced Odontogram أداة تفاعلية لتسجيل حالة الأسنان. يمكنك تسجيل النتائج سنًا تلو الآخر، وتخطيط العلاج، وتوثيق النسيج حول السني، وتصدير كل شيء بصيغة JSON أو FHIR أو تقرير PDF. تعمل بالكامل داخل المتصفح وتصلح للاستخدام بمفردها أو ضمن تطبيق أكبر.",
    "credits.creatorTitle": "المنشئ والمطور الرئيسي",
    "credits.contributorsTitle": "المساهمون",
    "credits.contrib.zoliqua": "منشئ المحرك بالكامل ومطوره الرئيسي.",
    "credits.contrib.odontodev": "ترطيب الحالة وواجهة برمجة دورة الحياة، وإعدادات الحشوات كخصائص متحكم بها، ودوال ضبط عديمة الأثر التكراري، وبطاقات قابلة للطي.",
    "credits.contrib.julianobazzi": "الترجمة إلى البرتغالية البرازيلية.",
    "credits.contrib.yassine": "الترجمة إلى الفرنسية والتشريح المقاس المقترح.",
    "credits.contrib.saegerdirk": "التشريح المقاس للأسنان ومولد الأسنان، إضافة إلى اقتراح الواجهة القابلة للتركيب.",
    "credits.librariesTitle": "بُني باستخدام",
    "credits.welcome": "المساهمات مرحب بها. افتح pull request على GitHub وسيُذكر اسمك هنا.",
    "credits.star": "ضع نجمة على GitHub",
    "credits.github": "اعرض على GitHub",
    "credits.close": "إغلاق"
